const llmOutput = items[0].json.text;

if (!llmOutput) {
  return items;
}

// More flexible regex that handles variations in spacing and formatting
const cleanedOutput = llmOutput
  .replace(/```html\n?/g, '')
  .replace(/```\n?/g, '')
  .trim();

// Split on the cover letter marker - try multiple variations
let parts = cleanedOutput.split(/###\s*COVER LETTER\s*###/i);
if (parts.length === 1) {
  parts = cleanedOutput.split(/COVER LETTER/i);
}

const cleanedResume = parts[0]
  .replace(/###\s*REWRITTEN RESUME\s*###/i, '')
  .trim();

const cleanedCoverLetter = parts[1] ? parts[1].trim() : '';

// Return with all original item data preserved
return items.map((item, index) => ({
  json: {
    ...item.json,
    cleanedCoverLetter: cleanedCoverLetter,
    cleanedResume: cleanedResume
  }
}));

const seen = new Set();

return items.filter(item => {
  const job = item.json;

  // Use the new, standardized fields and add optional chaining (?.) for safety
  const key = `${job.job_title}-${job.company_name}-${job.description?.substring(0, 100)}`;

  if (seen.has(key)) {
    return false;
  }
  seen.add(key);
  return true;
});

